const DISPLAY_DURATION=8000;const ANIMATION_DELAY=150;const ANIMATION_DURATION=700;document.addEventListener('DOMContentLoaded',function(){const messages=document.querySelectorAll('.message-alert');messages.forEach((message,index)=>{setTimeout(()=>{message.classList.remove('opacity-0','translate-x-full');},index*ANIMATION_DELAY);setTimeout(()=>{dismissMessage(message);},DISPLAY_DURATION+(index*ANIMATION_DELAY));});});function dismissMessage(element){element.classList.add('opacity-0','translate-x-full');setTimeout(()=>{if(element&&element.parentNode){element.remove();}},ANIMATION_DURATION);};